INSERT IGNORE INTO posts
  (section, slug, status, origin, title, excerpt, tag, coins, level, author, read_minutes, body, meta_description, focus_keyword, tags, featured, published_at, updated_at)
VALUES
('guias', 'golpes-com-cripto-como-reconhecer-e-se-proteger', 'published', 'manual', 'Golpes com cripto: como reconhecer e se proteger', 'Os golpes mais comuns com criptomoedas no Brasil, os sinais que se repetem em todos eles e o que fazer se você já caiu em um.', NULL, '["bitcoin","tether"]', 1, 'Redação Vibecoin', 8, '[{"type":"p","text":"Golpes com cripto mudam de nome a cada ano, mas quase todos usam os mesmos truques: promessa de ganho rápido, pressa para você decidir e um pedido para mandar dinheiro ou dados para alguém que você não conhece. Quem entende esses truques reconhece o golpe novo mesmo sem nunca ter ouvido falar dele. Este guia mostra os golpes mais comuns, os sinais que eles têm em comum e o que fazer se você já caiu em um."},{"type":"h2","text":"Por que a cripto atrai golpistas"},{"type":"p","text":"Uma transferência de criptomoeda, depois de confirmada na rede, não pode ser desfeita por um banco ou por uma central de atendimento. Não existe um \\"estorno\\" como no cartão de crédito. Além disso, muita gente ainda está aprendendo como as carteiras e as corretoras funcionam, e o golpista se aproveita dessa dúvida. Por isso, a melhor proteção é desconfiar antes de enviar, porque depois quase nunca há volta."},{"type":"h2","text":"Os golpes mais comuns"},{"type":"ul","items":["Pirâmide e \\"robô de investimento\\": prometem rendimento fixo alto, como 1% ao dia ou 30% ao mês, pagos por um robô de arbitragem ou de trade que ninguém pode ver funcionando. No começo, os primeiros recebem com o dinheiro dos que entram depois. Quando a entrada de gente nova diminui, os saques travam.","Falso suporte: depois que você reclama de uma corretora numa rede social, aparece um perfil parecido com o oficial oferecendo ajuda por mensagem privada. O objetivo é pegar a senha, o código de verificação ou a frase de recuperação da sua carteira.","Site ou aplicativo falso: um anúncio ou link leva a uma cópia da página de uma corretora ou carteira conhecida. Você digita login e senha, ou conecta a carteira, e o golpista usa esses dados.","Falso \\"airdrop\\" ou brinde: uma moeda desconhecida aparece na sua carteira, ou uma mensagem diz que você ganhou tokens. Para \\"resgatar\\", pedem que você conecte a carteira num site e aprove uma transação que, na verdade, dá permissão para retirar seus fundos.","Golpe do relacionamento: alguém puxa conversa por aplicativo de namoro ou rede social, ganha a sua confiança por semanas e só então apresenta uma \\"plataforma\\" onde diz ganhar muito. Os primeiros saques pequenos funcionam; os grandes, nunca.","Falsa recuperação de fundos: quem já perdeu dinheiro é procurado por supostos advogados, hackers ou órgãos públicos que prometem recuperar o valor mediante uma taxa adiantada. É um segundo golpe sobre a mesma vítima.","Celebridade falsa: vídeos editados ou perfis falsos de famosos e empresários anunciando uma plataforma ou um sorteio de bitcoin (\\"mande 0,1 e receba 0,2 de volta\\")."]},{"type":"h2","text":"Os sinais que se repetem"},{"type":"p","text":"Quase todo golpe tem pelo menos um destes sinais. Se você vir dois ou mais juntos, pare antes de enviar qualquer valor."},{"type":"ol","items":["Promessa de rendimento alto e garantido. Nenhum investimento real garante lucro, e cripto é um dos ativos que mais oscilam.","Pressa: \\"só hoje\\", \\"últimas vagas\\", \\"a taxa sobe amanhã\\". A pressa existe para você não pesquisar.","Pedido de senha, código de verificação ou frase de recuperação. Nenhuma corretora ou suporte de verdade pede isso.","Contato que começou do lado deles, por mensagem privada, e não por um canal que você mesmo procurou.","Pagamento para liberar um saque: taxa, imposto ou \\"desbloqueio\\" cobrado antes de você receber o próprio dinheiro.","Empresa que você não consegue achar em fontes independentes, ou que só aparece em anúncios e depoimentos.","Bônus por trazer amigos como parte principal do negócio. Quando o ganho depende de gente nova entrando, é sinal de pirâmide."]},{"type":"h2","text":"Como se proteger no dia a dia"},{"type":"ul","items":["Digite o endereço da corretora no navegador ou use o aplicativo oficial da loja. Evite clicar em links de anúncios, e-mails e mensagens.","Ligue a verificação em duas etapas por aplicativo autenticador, e não só por SMS.","Nunca digite a frase de recuperação da sua carteira em site nenhum. Ela só serve para restaurar a carteira no próprio aplicativo ou aparelho, e quem tem a frase tem o dinheiro.","Antes de aprovar uma transação na carteira, leia o que está sendo pedido. Pedido de \\"permissão ilimitada\\" num site desconhecido é sinal de alerta.","Confira se a empresa atua de forma regular no Brasil. O Banco Central regula as empresas que prestam serviços com criptoativos (Lei 14.478/2022), e a CVM publica alertas sobre empresas que oferecem investimentos sem autorização.","Comece com valores pequenos e teste o saque antes de colocar mais dinheiro em qualquer plataforma."]},{"type":"p","text":"Se você ainda não comprou sua primeira cripto, o guia [como comprar sua primeira cripto com segurança](/guias/como-comprar-sua-primeira-cripto-com-seguranca) mostra o caminho por uma corretora brasileira, e o [comparador de corretoras](/ferramentas/comparador-corretoras) reúne as taxas oficiais de algumas delas."},{"type":"h2","text":"Caí em um golpe. E agora?"},{"type":"ol","items":["Pare de enviar dinheiro, mesmo que peçam uma \\"última taxa\\" para liberar tudo.","Troque as senhas da corretora e do e-mail, e, se a frase de recuperação foi exposta, crie uma carteira nova e mova o que restou para ela.","Junte as provas: prints das conversas, endereço do site, comprovantes de Pix ou transferência e os códigos das transações na rede (hash).","Se o dinheiro saiu por Pix, avise o seu banco na hora e peça a abertura do Mecanismo Especial de Devolução (MED). Quanto antes, maior a chance de bloquear o valor na conta de destino.","Avise a corretora envolvida, pelo canal oficial. Às vezes ela consegue bloquear fundos que ainda estão lá.","Registre um boletim de ocorrência, que em muitos estados pode ser feito pela internet na delegacia virtual.","Desconfie de quem aparecer prometendo recuperar o dinheiro mediante pagamento. Esse é o golpe da falsa recuperação."]},{"type":"h2","text":"Resumo"},{"type":"p","text":"Nenhum investimento sério garante lucro, pede a sua frase de recuperação ou cobra para você sacar o próprio dinheiro. Na dúvida, não envie, pesquise o nome da empresa com a palavra \\"golpe\\" e converse com alguém de confiança antes. Veja também o [aviso de risco](/aviso-de-risco) e o guia sobre [carteiras fria, quente e autocustódia](/guias/carteira-fria-quente-e-autocustodia)."}]', 'Conheça os golpes mais comuns com criptomoedas, como pirâmide, falso suporte e falsa recuperação de fundos, os sinais de alerta e o que fazer se cair em um.', 'golpes com cripto', '["Segurança","Golpes","Cripto","Iniciantes"]', 0, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('guias', 'o-que-e-ethereum-e-para-que-serve', 'published', 'manual', 'O que é ethereum e para que serve', 'A rede que faz mais do que transferir dinheiro: contratos inteligentes, stablecoins, DeFi e NFTs, explicados sem jargão, com as diferenças para o bitcoin.', NULL, '["ethereum","bitcoin"]', 1, 'Redação Vibecoin', 7, '[{"type":"p","text":"O ethereum é uma rede de computadores espalhados pelo mundo que roda programas sem um dono central. O bitcoin foi criado para ser dinheiro digital; o ethereum foi criado para ser uma plataforma onde qualquer pessoa pode publicar aplicativos financeiros e de outros tipos. A moeda dessa rede é o ether, de símbolo ETH, usada para pagar as taxas de quem usa a rede. Este guia explica o que é o ethereum, para que ele serve e como ele se diferencia do bitcoin."},{"type":"h2","text":"Ethereum, ether e ETH"},{"type":"p","text":"No dia a dia, as pessoas chamam tudo de ethereum, mas há uma diferença: ethereum é o nome da rede, e ether (ETH) é a moeda que circula nela. Quando você vê a [cotação do ethereum](/cotacoes/ethereum), é o preço do ether. A rede foi proposta em 2013 por Vitalik Buterin e entrou no ar em julho de 2015, mantida por uma comunidade de desenvolvedores e pela Ethereum Foundation, uma organização sem fins lucrativos."},{"type":"h2","text":"Contratos inteligentes, sem jargão"},{"type":"p","text":"A grande novidade do ethereum são os contratos inteligentes: pequenos programas publicados na rede que executam sozinhos o que foi combinado. Pense numa máquina de refrigerante: você coloca a moeda, aperta o botão e a máquina entrega a lata, sem precisar de um vendedor. Um contrato inteligente funciona assim, só que com dinheiro digital: se a condição for cumprida, a transferência acontece, e ninguém pode mudar a regra no meio do caminho."},{"type":"p","text":"É por isso que se diz que o ethereum é \\"programável\\". Em cima dele foram criados milhares de aplicativos, chamados de dApps (aplicativos descentralizados)."},{"type":"h2","text":"Para que o ethereum é usado"},{"type":"ul","items":["Stablecoins: boa parte das moedas atreladas ao dólar, como USDT e USDC, circula na rede ethereum. Veja o guia [stablecoins: o que são e para que servem](/guias/stablecoins-o-que-sao-e-para-que-servem).","DeFi (finanças descentralizadas): empréstimos, trocas de moedas e rendimentos feitos por contratos inteligentes, sem banco no meio. O guia [DeFi sem susto](/guias/defi-sem-susto-rendimentos-e-riscos) explica de onde vêm os rendimentos e quais são os riscos.","Tokens: outras moedas e ativos criados em cima da rede, de projetos que não têm blockchain própria.","NFTs: certificados digitais únicos, usados em arte, ingressos e jogos.","Tokenização: representação de ativos do mundo real, como títulos públicos e fundos, em forma de token. Grandes gestoras e bancos já fizeram testes e lançamentos nessa área."]},{"type":"h2","text":"O que é a taxa de gas"},{"type":"p","text":"Cada operação na rede ethereum, de uma simples transferência a uma troca de moedas num aplicativo, tem um custo pago em ether, chamado de gas. A taxa varia com o movimento da rede: em horas de muito uso, fica mais cara. Para baratear, surgiram as redes de camada 2 (layer 2), como Arbitrum, Optimism e Base, que processam as operações fora da rede principal e registram o resultado nela depois. Nas corretoras brasileiras, quem só compra e vende ETH dentro da própria corretora não paga gas; ele aparece quando você transfere para uma carteira própria."},{"type":"h2","text":"Prova de participação: como a rede se mantém"},{"type":"p","text":"Desde setembro de 2022, num evento conhecido como The Merge, o ethereum funciona por prova de participação (proof of stake). Em vez de mineradores gastando energia, como no bitcoin, a rede é mantida por validadores que deixam ether travado como garantia. Quem valida certo recebe uma recompensa; quem tenta fraudar perde parte do que travou. A mudança reduziu o consumo de energia da rede em mais de 99%, segundo a Ethereum Foundation. Travar ether para receber recompensas é o que se chama de staking."},{"type":"h2","text":"Ethereum e bitcoin: as diferenças"},{"type":"ul","items":["Objetivo: o bitcoin quer ser dinheiro e reserva de valor; o ethereum quer ser uma plataforma de aplicativos.","Oferta: o bitcoin tem limite de 21 milhões de unidades; o ether não tem um limite fixo, e parte das taxas pagas na rede é destruída (\\"queimada\\"), o que reduz a emissão líquida.","Funcionamento: o bitcoin usa mineração (prova de trabalho); o ethereum usa validadores (prova de participação).","Risco: os dois oscilam muito de preço. No ethereum, há ainda o risco dos aplicativos construídos sobre ele, que podem ter falhas de programação."]},{"type":"p","text":"Para entender a moeda que veio primeiro, veja [o que é bitcoin, de verdade](/guias/o-que-e-bitcoin-de-verdade)."},{"type":"h2","text":"Como comprar e guardar"},{"type":"p","text":"O caminho mais simples é por uma corretora que atua no Brasil, com depósito em reais por Pix. Depois, você pode deixar o ether na corretora ou levar para uma carteira própria; as diferenças estão no guia [carteiras fria, quente e autocustódia](/guias/carteira-fria-quente-e-autocustodia). Ao transferir, confira a rede escolhida: mandar ETH pela rede errada é um dos erros mais comuns de quem começa. Lucro com a venda de ether segue as mesmas regras de imposto das outras criptomoedas, explicadas em [cripto no Imposto de Renda, passo a passo](/guias/cripto-no-imposto-de-renda-passo-a-passo)."},{"type":"p","text":"Este guia é informativo e não é recomendação de compra ou venda. Criptomoedas podem perder grande parte do valor em pouco tempo; leia o [aviso de risco](/aviso-de-risco)."}]', 'Entenda o que é ethereum, para que serve o ether (ETH), o que são contratos inteligentes e taxas de gas, e como ele se diferencia do bitcoin.', 'o que é ethereum', '["Ethereum","Contratos inteligentes","Cripto","Iniciantes"]', 0, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('guias', 'halving-do-bitcoin-o-que-e-e-quando-acontece', 'published', 'manual', 'Halving do bitcoin: o que é e quando acontece', 'Por que a emissão de bitcoin cai pela metade a cada quatro anos, o que aconteceu nos halvings anteriores e o que muda para quem tem a moeda.', NULL, '["bitcoin"]', 2, 'Redação Vibecoin', 7, '[{"type":"p","text":"O halving do bitcoin é o momento em que a quantidade de bitcoins novos criados a cada bloco cai pela metade. Ele acontece a cada 210 mil blocos, o que dá mais ou menos quatro anos, e está escrito nas regras da rede desde o início, em 2009. Ninguém decide a data: ela é consequência do ritmo em que os blocos são produzidos. Este guia explica como o halving funciona, as datas dos que já aconteceram e o que ele muda, ou não, para quem tem a moeda."},{"type":"h2","text":"De onde vêm os bitcoins novos"},{"type":"p","text":"A rede do bitcoin é mantida por mineradores: empresas e pessoas que usam computadores especializados para validar as transações e agrupá-las em blocos. Um bloco novo sai a cada 10 minutos, em média. Quem consegue fechar o bloco recebe uma recompensa formada por bitcoins recém-criados e pelas taxas pagas por quem fez as transações. É essa recompensa que coloca bitcoins novos em circulação, e é ela que o halving corta pela metade."},{"type":"h2","text":"As datas e as recompensas"},{"type":"ul","items":["2009: a rede começa com recompensa de 50 bitcoins por bloco.","Novembro de 2012 (1º halving): cai para 25.","Julho de 2016 (2º halving): cai para 12,5.","Maio de 2020 (3º halving): cai para 6,25.","Abril de 2024 (4º halving): cai para 3,125.","Próximo, previsto para 2028: deve cair para 1,5625. A data exata depende da velocidade dos blocos até lá."]},{"type":"p","text":"Como a recompensa vai diminuindo pela metade, a soma de todos os bitcoins que podem existir se aproxima de 21 milhões, mas nunca passa disso. Mais de 19 milhões já foram criados; as últimas frações devem ser emitidas por volta de 2140."},{"type":"h2","text":"Por que o halving existe"},{"type":"p","text":"O criador do bitcoin, que usou o pseudônimo Satoshi Nakamoto, escolheu uma emissão que diminui com o tempo para que a moeda fosse escassa e previsível, ao contrário do dinheiro emitido por bancos centrais, que pode aumentar conforme a política de cada país. A ideia é parecida com a do ouro: fica cada vez mais difícil encontrar unidades novas. Para entender o resto do funcionamento, veja [o que é bitcoin, de verdade](/guias/o-que-e-bitcoin-de-verdade)."},{"type":"h2","text":"O halving faz o preço subir?"},{"type":"p","text":"Essa é a pergunta mais comum, e a resposta honesta é: não dá para garantir. Depois dos halvings anteriores, o preço subiu muito nos meses seguintes, mas cada um desses períodos também teve outros acontecimentos ao mesmo tempo, como a entrada de investidores institucionais, mudanças nos juros dos Estados Unidos e a aprovação de fundos de bitcoin (ETFs). Com apenas quatro halvings na história, a amostra é pequena demais para tirar uma regra."},{"type":"p","text":"Há ainda um argumento a favor de efeitos menores com o tempo: cada halving corta uma fatia menor da oferta total, porque a maior parte dos bitcoins já existe. E o mercado sabe a data com anos de antecedência, então parte do efeito pode já estar no preço antes de o halving acontecer."},{"type":"h2","text":"O que muda para os mineradores"},{"type":"p","text":"Para os mineradores, o halving corta a receita em bitcoin pela metade de um dia para o outro. Quem tem máquinas antigas ou energia cara pode deixar de ter lucro e desligar os equipamentos. Com o tempo, a rede se ajusta: a dificuldade de mineração é recalculada a cada 2.016 blocos (cerca de duas semanas) para manter o ritmo de um bloco a cada 10 minutos. No longo prazo, a ideia é que as taxas das transações passem a pesar mais na remuneração dos mineradores do que os bitcoins novos."},{"type":"h2","text":"O que muda para quem tem bitcoin"},{"type":"ul","items":["Seus bitcoins não mudam: o halving não altera a quantidade que você tem nem a forma de guardar.","Não há nada a fazer na data. Não é preciso atualizar carteira nem trocar de corretora.","Desconfie de quem usa o halving para vender pressa (\\"compre antes que suba\\"). Esse discurso aparece em todo ciclo e é comum em golpes; veja [golpes com cripto: como reconhecer e se proteger](/guias/golpes-com-cripto-como-reconhecer-e-se-proteger)."]},{"type":"h2","text":"Resumo"},{"type":"p","text":"O halving é uma regra fixa do bitcoin que reduz pela metade a criação de moedas novas a cada 210 mil blocos, até o limite de 21 milhões. Ele torna a emissão previsível, mas não garante nenhum movimento de preço. Acompanhe a [cotação do bitcoin](/cotacoes/bitcoin) e, se for comprar, leia antes o [aviso de risco](/aviso-de-risco). Este guia é informativo e não é recomendação de compra ou venda."}]', 'Entenda o halving do bitcoin: por que a recompensa dos mineradores cai pela metade a cada 210 mil blocos, as datas dos halvings e o próximo, previsto para 2028.', 'halving do bitcoin', '["Bitcoin","Halving","Mineração","Oferta"]', 0, UTC_TIMESTAMP(), UTC_TIMESTAMP());
